1	//! [`RequestLedger`] — the account book of live requests, and the per-step
2	//! statement it ships on the step stream.
3	//!
4	//! One account per unanswered request. The driver opens it at
5	//! [`RequestLedger::register`]; exactly one terminal transition closes it
6	//! ([`RequestLedger::finish`], [`RequestLedger::fail`],
7	//! [`RequestLedger::reject`], [`RequestLedger::retire`], or
8	//! [`RequestLedger::defer_finish`]); accounts still open when the ledger
9	//! drops are written off as `Failed` terminals (engine teardown). Because
10	//! every open is a submit and every close is a terminal, "terminal exactly
11	//! once" and "nothing after the terminal" are enforced here: touching a
12	//! closed or unknown account panics at the offending scheduler call site.
13	//!
14	//! Token counts on terminals derive from the ledger's own tally
15	//! ([`RequestLedger::push_tokens`]), never from model-side arithmetic.
16	//!
17	//! Scheduler-facing methods are `pub`. Opening accounts and shipping the
18	//! statement ([`RequestLedger::register`], [`RequestLedger::commit_step`],
19	//! [`RequestLedger::fail_all`]) are `pub(crate)`: the driver owns the
20	//! cadence, and model crates cannot reach them.
21	
22	use std::collections::HashMap;
23	use std::sync::Arc;
24	use std::sync::atomic::AtomicBool;
25	use std::sync::atomic::Ordering;
26	use std::time::Instant;
27	
28	use super::event::FinishReason;
29	use super::event::TokenLogprob;
30	use super::request_lifecycle::DeferredFinish;
31	use super::request_lifecycle::RequestEnvelope;
32	use super::request_lifecycle::StepSender;
33	use super::step::PromptEcho;
34	use super::step::QueuedRequest;
35	use super::step::RejectReason;
36	use super::step::RequestId;
37	use super::step::RequestUpdate;
38	use super::step::ScheduledInfo;
39	use super::step::StepOutputs;
40	use super::step::Terminal;
41	
42	/// One open account: the request's admission facts and running tally. The
43	/// payload is not here — it went to the scheduler at `submit`; the account is
44	/// what the engine still owes the client.
45	struct Account {
46	    abort: Arc<AtomicBool>,
47	    prompt_len: usize,
48	    queued_at: Instant,
49	    state: AccountState,
50	}
51	
52	enum AccountState {
53	    /// Submitted, not yet admitted.
54	    Queued,
55	    /// Admitted; tokens tallied as they are pushed.
56	    Active { completion_tokens: usize },
57	}
58	
59	impl Account {
60	    fn completion_tokens(&self) -> usize {
61	        match self.state {
62	            AccountState::Queued => 0,
63	            AccountState::Active { completion_tokens } => completion_tokens,
64	        }
65	    }
66	}
67	
68	/// The current step's outgoing updates, merged per request so one step ships
69	/// at most one record per id.
70	#[derive(Default)]
71	struct StepStatement {
72	    buffer: Vec<Option<RequestUpdate>>,
73	    index: HashMap<RequestId, usize>,
74	}
75	
76	impl StepStatement {
77	    fn entry(&mut self, id: RequestId) -> &mut RequestUpdate {
78	        let slot = *self.index.entry(id).or_insert_with(|| {
79	            self.buffer.push(Some(RequestUpdate::empty(id)));
80	            self.buffer.len() - 1
81	        });
82	        self.buffer[slot]
83	            .as_mut()
84	            .expect("indexed step entry was extracted without index cleanup")
85	    }
86	
87	    /// Remove a request's buffered record (deferred finish, retire).
88	    fn extract(&mut self, id: RequestId) -> Option<RequestUpdate> {
89	        let slot = self.index.remove(&id)?;
90	        self.buffer[slot].take()
91	    }
92	
93	    fn take_updates(&mut self) -> Vec<RequestUpdate> {
94	        self.index.clear();
95	        self.buffer
96	            .drain(..)
97	            .flatten()
98	            .filter(|update| !update.is_vacant())
99	            .collect()
100	    }
101	}
102	
103	pub struct RequestLedger {
104	    accounts: HashMap<RequestId, Account>,
105	    statement: StepStatement,
106	    tx: StepSender,
107	}
108	
109	impl RequestLedger {
110	    pub(crate) fn new(tx: StepSender) -> Self {
111	        Self {
112	            accounts: HashMap::new(),
113	            statement: StepStatement::default(),
114	            tx,
115	        }
116	    }
117	
118	    fn account(&self, id: RequestId) -> &Account {
119	        self.accounts.get(&id).unwrap_or_else(|| {
120	            panic!("no open account for {id}: already answered, or never registered")
121	        })
122	    }
123	
124	    fn close(&mut self, id: RequestId) -> Account {
125	        self.accounts.remove(&id).unwrap_or_else(|| {
126	            panic!("no open account for {id}: already answered, or never registered")
127	        })
128	    }
129	
130	    // ── Queries ─────────────────────────────────────────────────────────
131	
132	    /// The frontend stopped wanting this request. The scheduler answers by
133	    /// [`Self::retire`] on its next touch; abort can land at any moment, so
134	    /// the probe belongs on every finish path too.
135	    pub fn is_aborted(&self, id: RequestId) -> bool {
136	        self.account(id).abort.load(Ordering::Acquire)
137	    }
138	
139	    /// Whether the account is open and admitted. For defensive paths that
140	    /// resolve effects for requests which may have been answered earlier in
141	    /// the same step (batch failure, duplicate effects).
142	    pub fn is_active(&self, id: RequestId) -> bool {
143	        matches!(
144	            self.accounts.get(&id),
145	            Some(Account {
146	                state: AccountState::Active { .. },
147	                ..
148	            })
149	        )
150	    }
151	
152	    /// Tokens shipped so far, from the ledger's tally.
153	    pub fn completion_tokens(&self, id: RequestId) -> usize {
154	        self.account(id).completion_tokens()
155	    }
156	
157	    // ── Queued-state exits ──────────────────────────────────────────────
158	
159	    /// Admit the request: stamp `scheduled_at` and buffer the admission facts.
160	    pub fn admit(&mut self, id: RequestId) {
161	        let account = self.accounts.get_mut(&id).unwrap_or_else(|| {
162	            panic!("no open account for {id}: already answered, or never registered")
163	        });
164	        assert!(
165	            matches!(account.state, AccountState::Queued),
166	            "admit on already-admitted request {id}"
167	        );
168	        account.state = AccountState::Active {
169	            completion_tokens: 0,
170	        };
171	        let scheduled = ScheduledInfo {
172	            queued_at: account.queued_at,
173	            scheduled_at: Instant::now(),
174	            prompt_tokens: account.prompt_len,
175	        };
176	        self.statement.entry(id).scheduled = Some(scheduled);
177	    }
178	
179	    /// Refuse the request at admission.
180	    pub fn reject(&mut self, id: RequestId, reason: RejectReason) {
181	        let account = self.close(id);
182	        assert!(
183	            matches!(account.state, AccountState::Queued),
184	            "reject after admission for {id}: an admitted request finishes or fails"
185	        );
186	        self.statement.entry(id).terminal = Some(Terminal::Rejected {
187	            reason,
188	            prompt_tokens: account.prompt_len,
189	        });
190	    }
191	
192	    // ── Streaming ───────────────────────────────────────────────────────
193	
194	    /// Append committed tokens. `logprobs` must be empty (none requested) or
195	    /// parallel to `ids`; the statement keeps the two aligned across pushes.
196	    pub fn push_tokens(&mut self, id: RequestId, ids: &[u32], logprobs: &[Option<TokenLogprob>]) {
197	        assert!(
198	            logprobs.is_empty() || logprobs.len() == ids.len(),
199	            "logprobs must be absent or parallel to tokens"
200	        );
201	        let account = self.accounts.get_mut(&id).unwrap_or_else(|| {
202	            panic!("no open account for {id}: already answered, or never registered")
203	        });
204	        let AccountState::Active { completion_tokens } = &mut account.state else {
205	            panic!("push_tokens on {id} before admission");
206	        };
207	        *completion_tokens += ids.len();
208	        let entry = self.statement.entry(id);
209	        entry.tokens.extend_from_slice(ids);
210	        if logprobs.is_empty() {
211	            entry.logprobs.extend(ids.iter().map(|_| None));
212	        } else {
213	            entry.logprobs.extend_from_slice(logprobs);
214	        }
215	    }
216	
217	    /// Report the prefix-cache hit count, in the step the scheduler learns it.
218	    pub fn set_cached_tokens(&mut self, id: RequestId, cached_tokens: usize) {
219	        assert!(
220	            self.is_active(id),
221	            "set_cached_tokens on {id} before admission"
222	        );
223	        self.statement.entry(id).cached_tokens = Some(cached_tokens);
224	    }
225	
226	    /// Echo the prompt back (echo mode), once, when prefill completes.
227	    pub fn echo_prompt(&mut self, id: RequestId, echo: PromptEcho) {
228	        assert!(self.is_active(id), "echo_prompt on {id} before admission");
229	        self.statement.entry(id).prompt_echo = Some(echo);
230	    }
231	
232	    /// Attach P/D handoff metadata to this step's record.
233	    pub fn kv_transfer(&mut self, id: RequestId, params: serde_json::Value) {
234	        assert!(self.is_active(id), "kv_transfer on {id} before admission");
235	        self.statement.entry(id).kv_transfer = Some(params);
236	    }
237	
238	    // ── Terminal transitions ────────────────────────────────────────────
239	
240	    /// Finish the request. Token counts come from the ledger's tally.
241	    pub fn finish(&mut self, id: RequestId, reason: FinishReason) {
242	        let account = self.close(id);
243	        let AccountState::Active { completion_tokens } = account.state else {
244	            panic!("finish on {id} before admission");
245	        };
246	        self.statement.entry(id).terminal = Some(Terminal::Finished {
247	            reason,
248	            prompt_tokens: account.prompt_len,
249	            completion_tokens,
250	        });
251	    }
252	
253	    /// Fail the request with an engine-side error. Valid in both states — a
254	    /// queued request can die to an engine error before admission.
255	    pub fn fail(&mut self, id: RequestId, message: impl Into<String>) {
256	        let account = self.close(id);
257	        self.statement.entry(id).terminal = Some(Terminal::Failed {
258	            message: message.into(),
259	            prompt_tokens: account.prompt_len,
260	            completion_tokens: account.completion_tokens(),
261	        });
262	    }
263	
264	    /// Close an aborted request's account (see [`Self::is_aborted`]). Silent,
265	    /// and discards anything buffered for it this step: the frontend already
266	    /// dropped its state for this id, so there is no one to address.
267	    pub fn retire(&mut self, id: RequestId) {
268	        let account = self.close(id);
269	        log::debug!(
270	            "request retired: frontend aborted: {id} tokens_shipped={}",
271	            account.completion_tokens()
272	        );
273	        self.statement.extract(id);
274	    }
275	
276	    /// Turn the request's finish into a token the scheduler can deliver later
277	    /// from any thread (P/D prefill roles gate `Finished` on KV-save
278	    /// visibility). Closes the account; the request's buffered update for
279	    /// this step — tokens included — folds into the returned message, so late
280	    /// delivery cannot reorder against the step stream.
281	    pub fn defer_finish(&mut self, id: RequestId, reason: FinishReason) -> DeferredFinish {
282	        let account = self.close(id);
283	        let AccountState::Active { completion_tokens } = account.state else {
284	            panic!("defer_finish on {id} before admission");
285	        };
286	        let mut update = self
287	            .statement
288	            .extract(id)
289	            .unwrap_or_else(|| RequestUpdate::empty(id));
290	        update.terminal = Some(Terminal::Finished {
291	            reason,
292	            prompt_tokens: account.prompt_len,
293	            completion_tokens,
294	        });
295	        DeferredFinish::new(update, self.tx.clone())
296	    }
297	
298	    // ── Driver face ─────────────────────────────────────────────────────
299	
300	    /// Open the account and hand back the [`QueuedRequest`] for
301	    /// [`super::Scheduler::submit`]. Consumes (and disarms) the envelope: from
302	    /// here on, the account carries the answer-on-drop duty.
303	    pub(crate) fn register(&mut self, envelope: RequestEnvelope) -> QueuedRequest {
304	        let inner = envelope.consume();
305	        let account = Account {
306	            abort: inner.abort,
307	            prompt_len: inner.request.prompt_tokens.len(),
308	            queued_at: inner.queued_at,
309	            state: AccountState::Queued,
310	        };
311	        let previous = self.accounts.insert(inner.id, account);
312	        assert!(previous.is_none(), "duplicate request id {}", inner.id);
313	        QueuedRequest {
314	            id: inner.id,
315	            request: inner.request,
316	        }
317	    }
318	
319	    /// Ship the step's statement as one message; a step that touched nothing
320	    /// ships nothing. Called once per driver iteration — model code never
321	    /// calls this (the driver owns the cadence).
322	    pub(crate) fn commit_step(&mut self) {
323	        let updates = self.statement.take_updates();
324	        if updates.is_empty() {
325	            return;
326	        }
327	        // A closed receiver means the frontend is gone; the driver notices
328	        // through the submission channel and winds down.
329	        let _ = self.tx.send(StepOutputs { updates });
330	    }
331	
332	    /// Write off every open account with one message — the driver's teardown
333	    /// sweep after a fatal `step` error, carrying the real error instead of
334	    /// the drop sweep's generic one.
335	    pub(crate) fn fail_all(&mut self, message: &str) {
336	        let ids: Vec<RequestId> = self.accounts.keys().copied().collect();
337	        for id in ids {
338	            self.fail(id, message);
339	        }
340	    }
341	}
342	
343	/// The teardown sweep: accounts still open when the ledger falls are engine
344	/// bugs or teardown races, and each must surface as a finished stream instead
345	/// of a client hang.
346	impl Drop for RequestLedger {
347	    fn drop(&mut self) {
348	        if self.accounts.is_empty() {
349	            return;
350	        }
351	        let updates = self
352	            .accounts
353	            .drain()
354	            .map(|(id, account)| {
355	                let message = match account.state {
356	                    AccountState::Queued => "request dropped by the engine before it was answered",
357	                    AccountState::Active { .. } => "request dropped by the engine mid-stream",
358	                };
359	                let mut update = RequestUpdate::empty(id);
360	                update.terminal = Some(Terminal::Failed {
361	                    message: message.to_string(),
362	                    prompt_tokens: account.prompt_len,
363	                    completion_tokens: account.completion_tokens(),
364	                });
365	                update
366	            })
367	            .collect();
368	        let _ = self.tx.send(StepOutputs { updates });
369	    }
370	}
371	
372	#[cfg(test)]
373	mod tests {
374	    use super::super::request_lifecycle::StepReceiver;
375	    use super::super::step::Request;
376	    use super::super::step::Terminal;
377	    use super::super::wiring::SchedulerHandle;
378	    use super::super::wiring::scheduler_pair;
379	    use super::*;
380	
381	    fn request(prompt: Vec<u32>) -> Request {
382	        Request {
383	            prompt_tokens: prompt,
384	            params: crate::sampler::SamplingParams::default(),
385	            max_tokens: 8,
