1	//! Wiring between one frontend and one scheduler, plus the engine bundle a
2	//! model line hands back from `launch`.
3	//!
4	//! Both ends of a scheduler are minted together by [`scheduler_pair`], so a
5	//! model crate cannot cross-wire or forget a line: the scheduler side arrives
6	//! as one [`SchedulerBackend`] value, the frontend side as one
7	//! [`SchedulerHandle`]. Channel choices per direction: the submit channel is
8	//! crossbeam (sync consumer on the scheduler thread; senders never block on
9	//! unbounded channels), the step stream is tokio (async consumer in the
10	//! protocol stack; the sync producer's send never blocks either), metrics are
11	//! a shared cell (read-only pull, deliberately unsubscribable — see
12	//! [`MetricsPublisher`]).
13	//!
14	//! How many schedulers an engine runs and what each one means (DP replicas,
15	//! anything else) is the model line's decision; the contract carries the
16	//! collection and attaches no rank semantics to it. Placement across
17	//! schedulers is frontend policy.
18	
19	use std::sync::Arc;
20	use std::sync::Mutex;
21	use std::sync::atomic::AtomicBool;
22	use std::sync::atomic::AtomicU64;
23	use std::sync::atomic::Ordering;
24	use std::time::Instant;
25	
26	use super::control::LoraClient;
27	use super::kv::KvCapacity;
28	use super::ledger::RequestLedger;
29	use super::metrics::SchedulerMetrics;
30	use super::request_lifecycle::RequestControl;
31	use super::request_lifecycle::RequestEnvelope;
32	use super::request_lifecycle::StepReceiver;
33	use super::step::Request;
34	use super::step::RequestId;
35	
36	/// Everything the scheduler thread consumes and produces. The driver
37	/// ([`super::drive`]) destructures this; model code only ever sees the
38	/// ledger, through the `step` argument.
39	pub struct SchedulerBackend {
40	    pub(crate) submissions: crossbeam_channel::Receiver<RequestEnvelope>,
41	    pub(crate) ledger: RequestLedger,
42	    pub(crate) metrics: MetricsPublisher,
43	}
44	
45	/// Sole writer of a scheduler's metrics cell; the driver publishes once per
46	/// iteration from [`super::Scheduler::metrics`].
47	///
48	/// Deliberately a plain cell and not a `watch` channel: the driver busy-polls,
49	/// so a subscription edge (`changed()`) would fire per spin and turn any
50	/// subscriber into a message flood at idle. With only
51	/// [`SchedulerHandle::metrics`] to read it, "notify me on metrics change" is
52	/// unrepresentable — consumers pull the snapshot at the moment they need one.
53	/// A `Mutex` (not per-field atomics) so a reader never sees fields torn
54	/// across two steps; both sides touch it uncontended for nanoseconds.
55	pub struct MetricsPublisher(Arc<Mutex<SchedulerMetrics>>);
56	
57	impl MetricsPublisher {
58	    pub(crate) fn publish(&self, snapshot: &SchedulerMetrics) {
59	        *self.0.lock().expect("metrics cell poisoned") = *snapshot;
60	    }
61	}
62	
63	/// The frontend's end of one running scheduler.
64	pub struct SchedulerHandle {
65	    submit_tx: crossbeam_channel::Sender<RequestEnvelope>,
66	    steps: Option<StepReceiver>,
